MM.mnemo[22] = {"cards":[{"id":"ko-k3-0375","w":"새다","cs":"téci; protékat; unikat (voda, plyn, světlo)","en":"to leak","p":"v","o":"k","ex":"다음 주에 또 샐 수도 있어요.","exc":"Příští týden to může zase protékat. (에 → kdy)","exa":"다음 주에 또 샐 수도 있어요. ⚠","h":"SE ≈ SÍTO: voda teče sítem.","m":"Používá se, když něco uniká skulinou nebo dírou: 물이 새다 (teče / protéká voda), 가스가 새다 (uniká plyn). Pozor na homonymum 새 (pták / nový)."},{"id":"ko-k3-0376","w":"막히다","cs":"být ucpaný (silnice), mít zácpu","en":"to be blocked, jammed (길이 막히다)","p":"v","o":"k","ex":"아침에 비가 많이 오면 길이 막힐 수도 있어요.","exc":"Když ráno hodně prší, na silnicích může být zácpa. (이 → 1. pád; -ㄹ 수도 있다 → možná)","exa":"아침에 비가 많이 오면 길이 막힐 수도 있어요. ⚠","h":"MA-KI ≈ MAKI: silnice ucpaná jako maki rolka rýží. 길이 막혀요 = je zácpa.","m":"Trpný tvar od 막다 (ucpat, zahradit). 길이 막혀요 = je zácpa, 코가 막혔어요 = mám ucpaný nos."},{"id":"ko-k3-0377","w":"고치다","cs":"opravit, spravit","en":"to fix","p":"v","o":"k","ex":"네, 고칠 수 있어요.","exc":"Ano, dokážu to opravit. (-ㄹ 수 있다 → moci)","exa":"네, 고칠 수 있어요. ⚠","h":"KO-ČI ≈ KOČÍ: kočí opravuje kolo vozu.","m":"„KOČÍ-da“: KOČÍ opraví kolo u kočáru a jede se dál. 고장 나다 = rozbít se, 고치다 = opravit."},{"id":"ko-k3-0378","w":"그만두다","cs":"přestat; skončit (v práci), dát výpověď","en":"to quit","p":"v","o":"k","ex":"저 회사 그만둘 수도 있어요.","exc":"Možná z té firmy odejdu. (-ㄹ 수도 있다 → možná)","exa":"저 회사 그만둘 수도 있어요. ⚠","h":"그만 = dost (KŮ-MAN ≈ KUMÁN): „Kumáne, dost! Dávám výpověď.“ 그만! = Přestaň!","m":"그만 „dost“ + 두다 „nechat“ = nech toho, dost! → skončit. 회사를 그만두다 = dát výpověď."},{"id":"ko-k3-0379","w":"가짜","cs":"falešný; padělek; napodobenina","en":"fake (가짜이다 = to be fake)","p":"n","o":"m","ex":"이거 가짜일 수도 있어요.","exc":"Tohle může být padělek.","h":"KA-ČA ≈ KAČKA: plastová kačka – falešná. Opak 진짜.","m":"假 falešný, nepravý + přípona -짜 = padělek, napodobenina. Stejnou koncovku má i přímý opak 진짜 (眞 pravý + -짜 = opravdový, skutečný).","r":["ga-假"]},{"id":"ko-k3-0382","w":"모자","cs":"čepice; klobouk; pokrývka hlavy","en":"hat","p":"n","o":"s","ex":"모자가 작을 수도 있어요.","exc":"Ta čepice může být malá. (가 → 1. pád)","h":"MO-DŽA ≈ MOZEK: čepice chrání mozek.","m":"帽 pokrývka hlavy + 子 přípona pro drobné předměty = čepice nebo klobouk. Vazba: 모자를 쓰다 = nasadit si čepici (sloveso 쓰다 jako u brýlí).","r":["mo-帽","ja-子"]},{"id":"ko-k3-0383","w":"다음 달","cs":"příští měsíc","en":"next month","p":"n","o":"k","ex":"저 다음 달에 일본 갈 수도 있어요.","exc":"Příští měsíc možná pojedu do Japonska. (에 → kdy)","h":"다음 = další (TAM) + 달 = měsíc (TAL ≈ TÁLO).","m":"다음 (další, následující) + 달 (měsíc) = příští měsíc. Řada měsíců: 지난 달 (minulý měsíc) → 이번 달 (tento měsíc) → 다음 달 (příští měsíc)."},{"id":"ko-k3-0384","w":"확실하다","cs":"jistý; zaručený; spolehlivý","en":"to be certain, sure","p":"a","o":"s","ex":"그런데 확실한 것은 아니에요.","exc":"Ale není to jisté. (은 → téma)","h":"HWAK-ŠIL ≈ „FAKT ŠÍLENĚ“: fakt šíleně jisté.","m":"確 jistý, pevný + 實 skutečný = naprosto jistý, zaručený. Příslovce 확실히 znamená ‚určitě, bezpochyby‘. Opak: 불확실하다 (nejistý).","r":["hwak-確","sil-實"]},{"id":"ko-k3-0385","w":"저녁","cs":"večer; večeře","en":"evening","p":"n","o":"k","ex":"오늘 저녁에 비가 올 수도 있어요.","exc":"Dnes večer může pršet. (에 → kdy; 가 → 1. pád)","h":"ČO-NJOK ≈ „CO NOC?“: večer před nocí. A taky večeře.","m":"Znamená denní dobu ‚večer‘ i jídlo ‚večeře‘ (stejně jako 아침 = ráno / snídaně a 점심 = poledne / oběd). Vazba: 저녁을 먹다 = večeřet."},{"id":"ko-k3-0386","w":"나중에","cs":"později; pak; potom","en":"later","p":"o","o":"k","ex":"그거 나중에 쓸 수도 있어요.","exc":"Tohle možná použiju později.","h":"NA-DŽUNG ≈ NA DŽUNGLI: na džungli pojedeme později.","m":"Časté rozloučení nebo odložení na jindy: 나중에 봐요! = Uvidíme se později! Opak: 먼저 (nejprve) nebo 아까 (před chvílí)."}],"gram":{"id":"ko-k3-g22","w":"-(으)ㄹ 수도 있어요","en":"Maybe I might…","cs":"možná…, je možné, že…, asi… (připuštění možnosti)","vy":"Vzorec -(으)ㄹ 수도 있어요 vznikl přidáním částice -도 (také, i) do vazby -(으)ㄹ 수 있어요 (moci, být schopen) a doslova znamená ‚existuje i ta možnost, že…‘. Vyjadřuje nejistotu nebo připuštění možnosti v přítomnosti či budoucnosti (‚možná…, mohlo by…, je možné, že…‘). Po samohlásce nebo ㄹ se připojuje -ㄹ 수도 있어요, po souhlásce -을 수도 있어요 a u podstatných jmen se sponou 이다 má tvar -일 수도 있어요.","m":"Stačí jedna slabika navíc: -(으)ㄹ 수 있어요 znamená ‚umím / můžu to udělat‘, kdežto přidáním -도 vznikne -(으)ㄹ 수도 있어요 ve významu ‚možná se to stane‘. Zápor se tvoří vložením 안 nebo 못 před sloveso (např. 안 갈 수도 있어요 = možná nepůjdu).","s":[["-(으)ㄹ 수 있다 → -(으)ㄹ 수도 있다","moci (je tu možnost…) → možná, mohlo by, snad (je tu i ta možnost, že…)"],["알 수도 있다 · 만날 수도 있다 · 작을 수도 있다","možná ví · možná se potkáme · možná je to malé"],["제 친구가 알 수도 있어요.","Můj kamarád to možná ví."],["내일 다시 만날 수도 있어요.","Zítra se možná zase uvidíme."],["모자가 작을 수도 있어요.","Ta čepice by mohla být malá."],["저 내일 올 수도 있어요.","Zítra sem možná přijdu."],["저 내일 안 올 수도 있어요.","Zítra sem možná nepřijdu."],["저 내일 못 올 수도 있어요.","Zítra sem možná nebudu moct přijít."],["이거 가짜일 수도 있어요.","Tohle by mohl být padělek."],["정말 그럴 수도 있어요.","Opravdu by to tak mohlo být."],["저 다음 달에 일본 갈 수도 있어요.","Příští měsíc možná pojedu do Japonska."],["그런데 확실한 것은 아니에요. 안 갈 수도 있어요.","Ale ještě to není jisté. Možná nepojedu."],["오늘 저녁에 비가 올 수도 있어요.","Dneska večer možná bude pršet."],["그거 나중에 쓸 수도 있어요.","Možná to později použiju."]]}};
